
import { useEffect, useState } from 'react'
import { supabase } from './services/supabase'

type HonorPeriod = {
  id: string
    period_month: string
      status: string
        calculated_at: string | null
          locked_at: string | null
            notes: string | null
            }

            type Teacher = {
              id: string
                full_name: string
                }

                type HonorDetail = {
                  id: string
                    teacher_id: string
                      attendance_date: string
                        session_number: number
                          assignment_type: string
                            attendance_status: string
                              rate_snapshot: number
                                honor_amount: number
                                  explanation: string | null
                                  }

                                  export default function HonorManagement() {
                                    const [periods, setPeriods] = useState<HonorPeriod[]>([])
                                      const [teachers, setTeachers] = useState<Teacher[]>([])
                                        const [details, setDetails] = useState<HonorDetail[]>([])
                                        const [selectedPeriodId, setSelectedPeriodId] = useState('')

                                        const [periodMonth, setPeriodMonth] = useState('')
                                        const [periodNotes, setPeriodNotes] = useState('')
                                        const [creatingPeriod, setCreatingPeriod] = useState(false)
                                        const [calculatingHonor, setCalculatingHonor] = useState(false)

                                          const [loading, setLoading] = useState(true)
                                            const [message, setMessage] = useState('')
                                            

                                              useEffect(() => {
                                                  loadInitialData()
                                                    }, [])

                                                      
                                                    async function loadInitialData() {
                                                      setLoading(true)
                                                        setMessage('')

                                                          const { data: periodData, error: periodError } = await supabase
                                                              .from('honor_periods')
                                                                  .select('id, period_month, status, calculated_at, locked_at, notes')
                                                                      .order('period_month', { ascending: false })

                                                                        const { data: teacherData, error: teacherError } = await supabase
                                                                            .from('teachers')
                                                                                .select('id')

                                                                                  if (periodError) {
                                                                                      setMessage(periodError.message)
                                                                                        } else {
                                                                                            setPeriods(periodData || [])
                                                                                              }

                                                                                                if (teacherError) {
                                                                                                    setMessage(teacherError.message)
                                                                                                        setTeachers([])
                                                                                                          } else {
                                                                                                              const teacherIds = (teacherData || []).map((teacher) => teacher.id)

                                                                                                                  if (teacherIds.length === 0) {
                                                                                                                        setTeachers([])
                                                                                                                            } else {
                                                                                                                                  const { data: userData, error: userError } = await supabase
                                                                                                                                          .from('users')
                                                                                                                                                  .select('id, full_name')
                                                                                                                                                          .in('id', teacherIds)
                                                                                                                                                                  .order('full_name')

                                                                                                                                                                        if (userError) {
                                                                                                                                                                                setMessage(userError.message)
                                                                                                                                                                                        setTeachers([])
                                                                                                                                                                                              } else {
                                                                                                                                                                                                      const teacherList = (teacherData || []).map((teacher) => ({
                                                                                                                                                                                                                id: teacher.id,
                                                                                                                                                                                                                          full_name:
                                                                                                                                                                                                                                      userData?.find((user) => user.id === teacher.id)?.full_name ||
                                                                                                                                                                                                                                                  'Nama tidak tersedia',
                                                                                                                                                                                                                                                          }))

                                                                                                                                                                                                                                                                  setTeachers(teacherList)
                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                setLoading(false)
                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                

                                                                                                                                                                                        async function loadPeriodDetails(periodId: string) {
                                                                                                                                                                                          setDetails([])
                                                                                                                                                                                            setMessage('')

                                                                                                                                                                                              const { data, error } = await supabase
                                                                                                                                                                                                  .from('honor_details')
                                                                                                                                                                                                      .select(`
                                                                                                                                                                                                            id,
                                                                                                                                                                                                                  teacher_id,
                                                                                                                                                                                                                        attendance_date,
                                                                                                                                                                                                                              session_number,
                                                                                                                                                                                                                                    assignment_type,
                                                                                                                                                                                                                                          attendance_status,
                                                                                                                                                                                                                                                rate_snapshot,
                                                                                                                                                                                                                                                      honor_amount,
                                                                                                                                                                                                                                                            explanation
                                                                                                                                                                                                                                                                `)
                                                                                                                                                                                                                                                                    .eq('period_id', periodId)
                                                                                                                                                                                                                                                                        .order('attendance_date', { ascending: true })

                                                                                                                                                                                                                                                                          if (error) {
                                                                                                                                                                                                                                                                              setMessage(error.message)
                                                                                                                                                                                                                                                                                  return
                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                      setDetails(data || [])
                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                      async function handleCreatePeriod() {
                                                                                                                                                                                                                                                                                        if (!periodMonth) {
                                                                                                                                                                                                                                                                                            setMessage('Silakan pilih bulan periode honor.')
                                                                                                                                                                                                                                                                                                return
                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                    setCreatingPeriod(true)
                                                                                                                                                                                                                                                                                                      setMessage('')

                                                                                                                                                                                                                                                                                                        const { data, error } = await supabase.rpc(
                                                                                                                                                                                                                                                                                                            'create_honor_period',
                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                      p_period_month: `${periodMonth}-01`,
                                                                                                                                                                                                                                                                                                                            p_notes: periodNotes || null,
                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                  )

                                                                                                                                                                                                                                                                                                                                    if (error) {
                                                                                                                                                                                                                                                                                                                                        setMessage(error.message)
                                                                                                                                                                                                                                                                                                                                            setCreatingPeriod(false)
                                                                                                                                                                                                                                                                                                                                                return
                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                    setPeriodNotes('')
                                                                                                                                                                                                                                                                                                                                                      setSelectedPeriodId(data)

                                                                                                                                                                                                                                                                                                                                                        await loadInitialData()
                                                                                                                                                                                                                                                                                                                                                          await loadPeriodDetails(data)

                                                                                                                                                                                                                                                                                                                                                            setCreatingPeriod(false)
                                                                                                                                                                                                                                                                                                                                                              setMessage('Periode honor berhasil dibuat.')
                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                              async function handleCalculateHonor() {
                                                                                                                                                                                                                                                                                                                                                                if (!selectedPeriodId) {
                                                                                                                                                                                                                                                                                                                                                                    setMessage('Silakan pilih periode honor terlebih dahulu.')
                                                                                                                                                                                                                                                                                                                                                                        return
                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                            const selectedPeriod = periods.find(
                                                                                                                                                                                                                                                                                                                                                                                (period) => period.id === selectedPeriodId
                                                                                                                                                                                                                                                                                                                                                                                  )

                                                                                                                                                                                                                                                                                                                                                                                    if (selectedPeriod?.status === 'locked') {
                                                                                                                                                                                                                                                                                                                                                                                        setMessage('Periode ini sudah dikunci dan tidak dapat dihitung ulang.')
                                                                                                                                                                                                                                                                                                                                                                                            return
                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                const confirmed = window.confirm(
                                                                                                                                                                                                                                                                                                                                                                                                    'Hitung ulang honor untuk periode yang dipilih?'
                                                                                                                                                                                                                                                                                                                                                                                                      )

                                                                                                                                                                                                                                                                                                                                                                                                        if (!confirmed) return

                                                                                                                                                                                                                                                                                                                                                                                                          setCalculatingHonor(true)
                                                                                                                                                                                                                                                                                                                                                                                                            setMessage('')

                                                                                                                                                                                                                                                                                                                                                                                                              const { error } = await supabase.rpc(
                                                                                                                                                                                                                                                                                                                                                                                                                  'calculate_honor_period',
                                                                                                                                                                                                                                                                                                                                                                                                                      {
                                                                                                                                                                                                                                                                                                                                                                                                                            p_period_id: selectedPeriodId,
                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                  )

                                                                                                                                                                                                                                                                                                                                                                                                                                    if (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                        setMessage(error.message)
                                                                                                                                                                                                                                                                                                                                                                                                                                            setCalculatingHonor(false)
                                                                                                                                                                                                                                                                                                                                                                                                                                                return
                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                    await loadInitialData()
                                                                                                                                                                                                                                                                                                                                                                                                                                                      await loadPeriodDetails(selectedPeriodId)

                                                                                                                                                                                                                                                                                                                                                                                                                                                        setCalculatingHonor(false)
                                                                                                                                                                                                                                                                                                                                                                                                                                                          setMessage('Perhitungan honor berhasil diselesaikan.')
                                                                                                                                                                                                                                                                                                                                                                                                                                                          }


                                                                                                                                                                                          return (
                                                                                                                                                                                              <div className="space-y-6">
                                                                                                                                                                                                    <div>
                                                                                                                                                                                                            <h2 className="text-2xl font-bold">
                                                                                                                                                                                                                      Rekap dan Pembayaran Honor
                                                                                                                                                                                                                              </h2>
                                                                                                                                                                                                                                      <p className="mt-1 text-sm text-gray-500">
                                                                                                                                                                                                                                                Pengelolaan rekap honor guru Madrasah Riyadhul Ilmi.
                                                                                                                                                                                                                                                        </p>
                                                                                                                                                                                                                                                              </div>

                                                                                                                                                                                                                                                              <div className="rounded-xl border border-gray-200 bg-white p-4 space-y-4">
                                                                                                                                                                                                                                                                <div>
                                                                                                                                                                                                                                                                    <h3 className="font-semibold text-gray-800">
                                                                                                                                                                                                                                                                          Buat Periode Honor
                                                                                                                                                                                                                                                                              </h3>
                                                                                                                                                                                                                                                                                  <p className="mt-1 text-xs text-gray-500">
                                                                                                                                                                                                                                                                                        Buat periode bulanan untuk menghitung honor guru.
                                                                                                                                                                                                                                                                                            </p>
                                                                                                                                                                                                                                                                                              </div>

                                                                                                                                                                                                                                                                                                <div>
                                                                                                                                                                                                                                                                                                    <label className="mb-2 block text-sm font-medium text-gray-700">
                                                                                                                                                                                                                                                                                                          Bulan Periode
                                                                                                                                                                                                                                                                                                              </label>
                                                                                                                                                                                                                                                                                                                  <input
                                                                                                                                                                                                                                                                                                                        type="month"
                                                                                                                                                                                                                                                                                                                              value={periodMonth}
                                                                                                                                                                                                                                                                                                                                    onChange={(e) => setPeriodMonth(e.target.value)}
                                                                                                                                                                                                                                                                                                                                          className="w-full rounded-lg border border-gray-300 p-3 text-sm"
                                                                                                                                                                                                                                                                                                                                              />
                                                                                                                                                                                                                                                                                                                                                </div>

                                                                                                                                                                                                                                                                                                                                                  <div>
                                                                                                                                                                                                                                                                                                                                                      <label className="mb-2 block text-sm font-medium text-gray-700">
                                                                                                                                                                                                                                                                                                                                                            Catatan (Opsional)
                                                                                                                                                                                                                                                                                                                                                                </label>
                                                                                                                                                                                                                                                                                                                                                                    <textarea
                                                                                                                                                                                                                                                                                                                                                                          value={periodNotes}
                                                                                                                                                                                                                                                                                                                                                                                onChange={(e) => setPeriodNotes(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                      placeholder="Tambahkan catatan periode..."
                                                                                                                                                                                                                                                                                                                                                                                            rows={3}
                                                                                                                                                                                                                                                                                                                                                                                                  className="w-full rounded-lg border border-gray-300 p-3 text-sm"
                                                                                                                                                                                                                                                                                                                                                                                                      />
                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                          <button
                                                                                                                                                                                                                                                                                                                                                                                                              type="button"
                                                                                                                                                                                                                                                                                                                                                                                                                  onClick={handleCreatePeriod}
                                                                                                                                                                                                                                                                                                                                                                                                                      disabled={creatingPeriod || !periodMonth}
                                                                                                                                                                                                                                                                                                                                                                                                                          className="w-full rounded-lg bg-blue-600 px-4 py-3 text-sm font-semibold text-white disabled:opacity-50"
                                                                                                                                                                                                                                                                                                                                                                                                                            >
                                                                                                                                                                                                                                                                                                                                                                                                                                {creatingPeriod ? 'Membuat Periode...' : 'Buat Periode'}
                                                                                                                                                                                                                                                                                                                                                                                                                                  </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                  {selectedPeriodId && (
                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="rounded-xl border border-gray-200 bg-white p-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="mb-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                              <h3 className="font-semibold text-gray-800">
                                                                                                                                                                                                                                                                                                                                                                                                                                                      Proses Perhitungan
                                                                                                                                                                                                                                                                                                                                                                                                                                                            </h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p className="mt-1 text-xs text-gray-500">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Hitung honor berdasarkan jadwal dan kehadiran guru.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              type="button"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onClick={handleCalculateHonor}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          disabled={
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  calculatingHonor ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          periods.find((period) => period.id === selectedPeriodId)?.status === 'locked'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      className="w-full rounded-lg bg-emerald-600 px-4 py-3 text-sm font-semibold text-white disabled:opacity-50"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {calculatingHonor ? 'Menghitung Honor...' : 'Hitung Honor'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}



                                                                                                                                                                                                                                                                    {loading && (
                                                                                                                                                                                                                                                                            <p className="text-sm text-gray-500">
                                                                                                                                                                                                                                                                                      Memuat data...
                                                                                                                                                                                                                                                                                              </p>
                                                                                                                                                                                                                                                                                                    )}

                                                                                                                                                                                                                                                                                                    <div className="rounded-xl border border-gray-200 bg-white p-4 space-y-3">
                                                                                                                                                                                                                                                                                                      <label className="block text-sm font-medium text-gray-700">
                                                                                                                                                                                                                                                                                                          Pilih Periode Honor
                                                                                                                                                                                                                                                                                                            </label>

                                                                                                                                                                                                                                                                                                              <select
                                                                                                                                                                                                                                                                                                                  value={selectedPeriodId}
                                                                                                                                                                                                                                                                                                                      onChange={(e) => {
                                                                                                                                                                                                                                                                                                                            const periodId = e.target.value
                                                                                                                                                                                                                                                                                                                                  setSelectedPeriodId(periodId)

                                                                                                                                                                                                                                                                                                                                        if (periodId) {
                                                                                                                                                                                                                                                                                                                                                loadPeriodDetails(periodId)
                                                                                                                                                                                                                                                                                                                                                      } else {
                                                                                                                                                                                                                                                                                                                                                              setDetails([])
                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                        }}
                                                                                                                                                                                                                                                                                                                                                                            className="w-full rounded-lg border border-gray-300 p-3 text-sm"
                                                                                                                                                                                                                                                                                                                                                                              >
                                                                                                                                                                                                                                                                                                                                                                                  <option value="">Pilih periode...</option>

                                                                                                                                                                                                                                                                                                                                                                                      {periods.map((period) => (
                                                                                                                                                                                                                                                                                                                                                                                            <option key={period.id} value={period.id}>
                                                                                                                                                                                                                                                                                                                                                                                                    {new Date(period.period_month + 'T00:00:00').toLocaleDateString(
                                                                                                                                                                                                                                                                                                                                                                                                              'id-ID',
                                                                                                                                                                                                                                                                                                                                                                                                                        { month: 'long', year: 'numeric' }
                                                                                                                                                                                                                                                                                                                                                                                                                                )} — {period.status}
                                                                                                                                                                                                                                                                                                                                                                                                                                      </option>
                                                                                                                                                                                                                                                                                                                                                                                                                                          ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                            </select>
                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>

                                                                                                                                                                                                                           {selectedPeriodId && (
                                                                                                                                                                                                                             <div className="rounded-xl border border-gray-200 bg-white p-4">
                                                                                                                                                                                                                                 <p className="text-xs text-gray-500">
                                                                                                                                                                                                                                       Status Periode
                                                                                                                                                                                                                                           </p>

                                                                                                                                                                                                                                               <p className="mt-2 font-semibold text-gray-800">
                                                                                                                                                                                                                                                     {periods.find((period) => period.id === selectedPeriodId)?.status === 'draft'
                                                                                                                                                                                                                                                             ? 'Draft — Belum Dihitung'
                                                                                                                                                                                                                                                                     : periods.find((period) => period.id === selectedPeriodId)?.status === 'calculated'
                                                                                                                                                                                                                                                                             ? 'Sudah Dihitung — Menunggu Pemeriksaan'
                                                                                                                                                                                                                                                                                     : periods.find((period) => period.id === selectedPeriodId)?.status === 'locked'
                                                                                                                                                                                                                                                                                             ? 'Terkunci'
                                                                                                                                                                                                                                                                                                     : 'Status Tidak Diketahui'}
                                                                                                                                                                                                                                                                                                         </p>
                                                                                                                                                                                                                                                                                                           </div>
                                                                                                                                                                                                                                                                                                           )}



                                                                                                                                                                                                                                                                                                          {message && (
                                                                                                                                                                                                                                                                                                                  <div className="rounded-lg bg-red-50 p-3 text-sm text-red-700">
                                                                                                                                                                                                                                                                                                                            {message}
                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                          )}

                                                                                                                                                                                                                                                                                                                                                {selectedPeriodId && (
                                                                                                                                                                                                                                                                                                                                                  <div className="grid grid-cols-2 gap-3">
                                                                                                                                                                                                                                                                                                                                                      <div className="rounded-xl border border-gray-200 bg-white p-4">
                                                                                                                                                                                                                                                                                                                                                            <p className="text-xs text-gray-500">
                                                                                                                                                                                                                                                                                                                                                                    Jumlah Detail
                                                                                                                                                                                                                                                                                                                                                                          </p>
                                                                                                                                                                                                                                                                                                                                                                                <p className="mt-2 text-2xl font-bold">
                                                                                                                                                                                                                                                                                                                                                                                        {details.length}
                                                                                                                                                                                                                                                                                                                                                                                              </p>
                                                                                                                                                                                                                                                                                                                                                                                                  </div>

                                                                                                                                                                                                                                                                                                                                                                                                      <div className="rounded-xl border border-gray-200 bg-white p-4">
                                                                                                                                                                                                                                                                                                                                                                                                            <p className="text-xs text-gray-500">
                                                                                                                                                                                                                                                                                                                                                                                                                    Total Honor
                                                                                                                                                                                                                                                                                                                                                                                                                          </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                <p className="mt-2 text-lg font-bold text-emerald-700">
                                                                                                                                                                                                                                                                                                                                                                                                                                        {details
                                                                                                                                                                                                                                                                                                                                                                                                                                                  .reduce((total, item) => total + Number(item.honor_amount || 0), 0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                            .toLocaleString('id-ID', {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        style: 'currency',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    currency: 'IDR',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                maximumFractionDigits: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {selectedPeriodId && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="overflow-hidden rounded-xl border border-gray-200 bg-white">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="border-b border-gray-100 p-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <h3 className="font-semibold text-gray-800">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Rincian Honor Mengajar
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p className="mt-1 text-xs text-gray-500">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Rincian kehadiran dan honor setiap sesi.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {details.length === 0 ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p className="p-4 text-sm text-gray-500">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Belum ada rincian honor untuk periode ini.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="overflow-x-auto">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <table className="w-full text-left text-sm">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <thead className="bg-gray-50 text-xs text-gray-500">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <th className="p-3">Tanggal</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <th className="p-3">Guru</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <th className="p-3">Sesi</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <th className="p-3">Jenis</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <th className="p-3">Status</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <th className="p-3 text-right">Honor</th>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </thead>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {details.map((item) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <tr key={item.id} className="border-t border-gray-100">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <td className="whitespace-nowrap p-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {new Date(item.attendance_date + 'T00:00:00').toLocaleDateString('id-ID')}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <td className="p-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {teachers.find(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              (teacher) => teacher.id === item.teacher_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )?.full_name || 'Guru tidak ditemukan'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <td className="p-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {item.session_number}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <td className="p-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {item.assignment_type === 'replacement'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ? 'Pengganti'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            : 'Reguler'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <td className="p-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {item.attendance_status === 'present'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ? 'Hadir'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      : item.attendance_status === 'late'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ? 'Terlambat'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              : item.attendance_status === 'approved_leave'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ? 'Izin Disetujui'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      : item.attendance_status === 'absent'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ? 'Tidak Hadir'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              : item.attendance_status === 'replacement_not_attended'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ? 'Pengganti Tidak Hadir'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      : item.attendance_status}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </td>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <td className="whitespace-nowrap p-3 text-right font-medium">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {Number(item.honor_amount).toLocaleString('id-ID', {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    style: 'currency',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        currency: 'IDR',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            maximumFractionDigits: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </td>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </tr>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </table>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }